    }

    public BigDecimal getPrice() {
        return price;
    }

    public void setPrice(BigDecimal price) {
        this.price = price;
    }

    public AllergensAsEmbeddable getAllergens() {
        return allergens;
    }

    public void setAllergens(AllergensAsEmbeddable allergens) {
        this.allergens = allergens;
    }

    public Long getId() {
        return id;
