        if (o == null || getClass() != o.getClass())
            return false;

        Artist artist = (Artist) o;

        return Objects.equals(id, artist.id);
    }

    @Override
    public int hashCode() {
        return id != null ? id.hashCode() : 0;
    }

    protected Artist() {
    }
}

